import resonance.si as si
import resonance.db as db
import numpy as np
from resonance.internal import declare_transformation, Processor


@declare_transformation
class transform_window_to_channels(Processor):
    def __init__(self):
        self._si = None
        self._transform = None

    def prepare(self, input: db.Window, channels, pass_metadata=False):
        if not isinstance(input, db.Window):
            raise Exception("input must be window")
        self._channels = channels
        self._window = input.SI.samples
        self._prealloc = np.zeros((self._channels, self._window))

        self._si = si.Channels(channels=self._channels, samplingRate=input.SI.samplingRate)
        return self._si

    def online(self, windows):
        def transform_window(wnd: db.SingleWindow):
            return wnd[:]
        
        return db.Channels(self._si, [wnd.timestamps[-1] for wnd in windows], [transform_window(wnd) for wnd in windows])